    public static int[][] criarMapaBase() {
        int[][] mapa = copiar(cenario3DoJogo);
        // O editor exporta a trilha como 53; no motor esse ID antigo é sólido.
        // O ID 5 tem o mesmo visual de terra e permite percorrer os caminhos.
        for (int[] linha : mapa) {
            for (int coluna = 0; coluna < linha.length; coluna++) {
                if (linha[coluna] == 53) linha[coluna] = 5;
            }
        }
        return mapa;
    }

    public static int[][] criarCamadaObjetos() {
        int[][] objetos = copiar(cenario3Objetos);
        // Mantém livre o nascimento já usado ao continuar após o final (745, 335).
        objetos[7][15] = -1;
        objetos[7][16] = -1;
        return objetos;
    }

    private static int[][] copiar(int[][] original) {
        int[][] copia = new int[original.length][];
        for (int linha = 0; linha < original.length; linha++) {
            copia[linha] = original[linha].clone();
        }
        return copia;
    }

